    ext=set(); q=C.deque()
    seeds=[(y,x) for y in (0,H-1) for x in range(W) if t[y][x]==0]+[(y,x) for x in (0,W-1) for y in range(H) if t[y][x]==0]
    for y,x in seeds: ext.add((y,x)); q.append((y,x))
    while q:
        y,x=q.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and t[ny][nx]==0 and (ny,nx) not in ext:
                ext.add((ny,nx)); q.append((ny,nx))
    out=[r[:] for r in t]
    for y in range(H):
        for x in range(W):
            if t[y][x]==0 and (y,x) not in ext: out[y][x]=2
    comps=[]; seen=[[False]*W for _ in range(H)]
    for y in range(H):
        for x in range(W):
            if t[y][x]==5 and not seen[y][x]:
                st=[(y,x)];seen[y][x]=True;comp=[]
                while st:
                    cy,cx=st.pop();comp.append((cy,cx))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and t[ny][nx]==5 and not seen[ny][nx]:
                            seen[ny][nx]=True;st.append((ny,nx))
                comps.append(comp)
    for comp in comps:
        ys=[c[0] for c in comp]; xs=[c[1] for c in comp]
        r0,r1=min(ys),max(ys); c0,c1=min(xs),max(xs)
        cs={(y,x) for y,x in comp}
        for y in range(r0,r1+1):
            for x in range(c0,c1+1):
                if (y,x) in cs: continue
                if t[y][x]==0: 
                    out[y][x]=2
                    # hole: interior cell with an exterior neighbor? use direct: cell in top row of comp with 0 above
                    if y==r0:
                        pass
        holes=[(r0,x) for x in range(c0,c1+1) if t[r0][x]==0 and (r0,x) not in cs]
        for hy,hx in holes: out[hy][hx]=2
        # run lengths: columns whose entire column below hy is free of 5 (anywhere), skipping columns that are the comp's own columns?
        def ok(c):
            return not any(r1_c:=t[r][c]==5 for r in range(hy+1,H))
        LL=[d for d in range(1,W) if 0<=hx-d<W and all(ok(hx-d) for _ in [0])]
        RR=[d for d in range(1,W) if hx+d<W and all(ok(hx+d) for _ in [0])]
        dirs='R' if max(RR,default=0)>=max(LL,default=0) else 'L'
        for x in (range(hx+1,W) if dirs=='R' else range(0,hx)):
            if hy-1>=0 and 0<=x<W and out[hy-1][x]==0: out[hy-1][x]=2
    return out
